package com.company.platform.commerce.domain.pricing;
import java.math.BigDecimal; import java.util.Currency;
public record Money(BigDecimal amount,Currency currency) { public Money { if(amount==null||currency==null||amount.scale()>4||amount.signum()<0) throw new IllegalArgumentException("invalid money"); } public Money add(Money other){sameCurrency(other);return new Money(amount.add(other.amount),currency);} public Money subtract(Money other){sameCurrency(other);var result=amount.subtract(other.amount);if(result.signum()<0)throw new IllegalArgumentException("money cannot be negative");return new Money(result,currency);} public Money percentageDiscount(BigDecimal percentage){if(percentage==null||percentage.signum()<0||percentage.compareTo(BigDecimal.valueOf(100))>0)throw new IllegalArgumentException("invalid discount");return new Money(amount.multiply(BigDecimal.ONE.subtract(percentage.movePointLeft(2))).setScale(4,java.math.RoundingMode.HALF_UP),currency);} private void sameCurrency(Money other){if(other==null||!currency.equals(other.currency))throw new IllegalArgumentException("currency mismatch");} }
